package com.mauri.juryroster;
import java.util.*;
import org.json.*;
public final class MeetingTests {
 static int n=0;static void check(boolean b,String label){if(!b)throw new AssertionError(label);n++;}
 static Set<Integer> weeks(Integer... i){return new LinkedHashSet<>(Arrays.asList(i));}
 static void fail(Runnable action){try{action.run();throw new AssertionError("Expected invalid meeting action");}catch(IllegalArgumentException expected){n++;}}
 static RosterCore.Person p(String name,String role,String status){RosterCore.Person p=new RosterCore.Person();p.court.put("firstName",name);p.court.put("lastName","Synthetic");p.court.put("role",role);p.court.put("status",status);return p;}
 public static void main(String[] args)throws Exception{
  MeetingBook b=new MeetingBook();check(b.meetings.isEmpty(),"No real meetings fabricated on migration");check(b.patternDates(3,weeks(1,3),"2027-01-01","2027-01-31").equals(Arrays.asList("2027-01-06","2027-01-20")),"First and third Wednesdays in January");
  check(b.patternDates(2,weeks(2,4),"2027-01-01","2027-02-28").equals(Arrays.asList("2027-01-12","2027-01-26","2027-02-09","2027-02-23")),"Alternative county pattern");check(b.patternDates(1,weeks(5),"2027-02-01","2027-02-28").isEmpty(),"Nonexistent fifth weekday omitted");
  check(b.generate(3,weeks(1,3),"2026-11-01","2027-06-30")==16,"Generate term span");check(b.generate(3,weeks(1,3),"2026-11-01","2027-06-30")==0,"Repeated generation does not duplicate");MeetingBook.Meeting jan=b.meetings.stream().filter(m->m.date.equals("2027-01-06")).findFirst().get();check(jan.state.equals("Scheduled")&&!jan.started,"January cancellation not assumed");
  RosterCore.Person juror=p("Alex","Juror","Active"),alternate=p("Casey","Alternate","Active"),resigned=p("Jordan","Juror","Resigned");List<RosterCore.Person> roster=Arrays.asList(juror,alternate,resigned);b.start(jan.id,roster);check(jan.members.size()==2&&!jan.members.containsKey(resigned.id),"Starts from active members regardless of roster display filters");check(jan.members.values().stream().allMatch(m->m.status.equals("Not recorded")),"Initial attendance unrecorded");b.mark(jan.id,juror.id,"Present");check(jan.members.get(juror.id).status.equals("Present"),"Attendance mark saved");int history=jan.history.size();b.mark(jan.id,juror.id,"Present");check(jan.history.size()==history,"Repeated same mark has no spurious audit");
  alternate.court.put("role","Juror");juror.court.put("status","Resigned");juror.court.put("firstName","Changed");b.start(jan.id,roster);check(jan.members.get(alternate.id).role.equals("Alternate")&&jan.members.get(juror.id).name.equals("Alex Synthetic"),"Snapshot names and roles survive later roster changes");
  b.cancel(jan.id,"Holiday break");check(jan.members.get(juror.id).status.equals("Present"),"Cancellation retains attendance");fail(()->b.mark(jan.id,juror.id,"Absent"));b.generate(3,weeks(1,3),"2026-11-01","2027-06-30");check(jan.state.equals("Cancelled"),"Regenerate never revives cancellation");b.restore(jan.id);check(jan.state.equals("Scheduled"),"Cancelled meeting restored");
  b.remove(jan.id);check(jan.state.equals("Deleted")&&jan.members.get(juror.id).status.equals("Present"),"Removal soft deletes and retains history");check(b.generate(3,weeks(1,3),"2026-11-01","2027-06-30")==0,"Removed date not recreated");b.restore(jan.id);b.edit(jan.id,"2027-01-07","Special meeting","Revised date");check(jan.members.get(juror.id).status.equals("Present")&&b.excludedDates.contains("2027-01-06"),"Moving retains attendance and old-date exception");check(b.generate(3,weeks(1,3),"2026-11-01","2027-06-30")==0,"Rescheduled old date not regenerated");MeetingBook.Meeting special=b.add("2027-01-06","Manually restored date");check(!special.id.equals(jan.id),"Reusing a former date gets a stable new ID");
  fail(()->b.add("2027-01-06","Duplicate"));fail(()->b.add("2027-02-30","Invalid date"));fail(()->b.edit(jan.id,"2027-01-20","Conflict",""));fail(()->b.patternDates(3,weeks(),"2027-01-01","2027-02-01"));fail(()->b.patternDates(0,weeks(1),"2027-01-01","2027-02-01"));fail(()->b.patternDates(3,weeks(1),"2027-03-01","2027-01-01"));fail(()->b.patternDates(3,weeks(1),"2027-01-01","2030-01-01"));
  b.addMember(jan.id,resigned);check(jan.members.containsKey(resigned.id),"Former member can be added to a historical meeting");fail(()->b.removeMember(jan.id,juror.id));b.mark(jan.id,juror.id,"Not recorded");b.removeMember(jan.id,juror.id);check(!jan.members.containsKey(juror.id),"Unmarked participant removable");fail(()->b.mark(jan.id,alternate.id,"Unknown"));
  b.remove(special.id);b.add("2027-01-06","Replacement meeting");fail(()->b.restore(special.id));check(special.state.equals("Deleted"),"Restore date conflict leaves removed history unchanged");
  RosterCore r=new RosterCore();r.meetingBook=b;Collections.addAll(r.people,juror,alternate,resigned);byte[] bytes=Store.encode(r);RosterCore reopened=Store.decode(bytes);check(reopened.meetingBook.get(jan.id).members.get(alternate.id).role.equals("Alternate")&&reopened.meetingBook.get(jan.id).notes.equals("Revised date"),"Meeting snapshot and notes survive store/handoff");check(reopened.meetingBook.excludedDates.equals(b.excludedDates)&&reopened.meetingBook.get(special.id).state.equals("Deleted"),"Exceptions and removed meetings survive handoff");
  char[] pass="Synthetic meeting password".toCharArray();RosterCore decrypted=Store.decode(HandoffCrypto.decrypt(HandoffCrypto.encrypt(bytes,pass),pass));check(decrypted.meetingBook.meetings.size()==b.meetings.size(),"Encrypted handoff contains meetings");
  JSONObject legacy=new JSONObject(new String(bytes,"UTF-8"));legacy.remove("meetingBook");RosterCore old=Store.decode(legacy.toString().getBytes("UTF-8"));check(old.people.size()==3&&old.meetingBook.meetings.isEmpty(),"Old roster migration retains people and starts empty meetings");String csv=new String(b.csv(),"UTF-8");check(csv.contains("Deleted")&&csv.contains("Casey Synthetic")&&csv.contains("Alternate"),"Attendance export includes historical and removed records");
  JSONObject duplicate=b.toJson();duplicate.getJSONArray("meetings").put(duplicate.getJSONArray("meetings").getJSONObject(0));try{MeetingBook.fromJson(duplicate);throw new AssertionError("Duplicate meeting ID accepted");}catch(IllegalArgumentException expected){n++;}
  MeetingBook quick=new MeetingBook();RosterCore.Person active=p("Taylor","Juror","Active");List<RosterCore.Person> people=Arrays.asList(active,resigned);MeetingBook.Meeting today=quick.add("2026-10-29","Meeting");check(quick.scheduledOn("2026-10-28")==null&&!today.started,"Off-day roster does not show or start attendance");
  quick.markFromRoster(today.id,active,"In person","2026-10-29",people);check(today.members.get(active.id).status.equals("In person")&&quick.summary(today).startsWith("1 present"),"Roster in-person mark counts present");
  quick.markFromRoster(today.id,active,"Online","2026-10-29",people);check(today.members.get(active.id).status.equals("Online")&&today.members.size()==1&&quick.summary(today).startsWith("1 present"),"Online replaces in-person without double counting");
  fail(()->quick.markFromRoster(today.id,active,"Online","2026-10-30",people));fail(()->quick.markFromRoster(today.id,resigned,"Online","2026-10-29",people));
  check(MeetingBook.fromJson(quick.toJson()).get(today.id).members.get(active.id).status.equals("Online")&&new String(quick.csv(),"UTF-8").contains("Online"),"Attendance mode survives handoff and CSV");
  quick.markFromRoster(today.id,active,"Not recorded","2026-10-29",people);check(today.members.get(active.id).status.equals("Not recorded")&&quick.summary(today).startsWith("0 present"),"Unticking restores unrecorded");
  quick.cancel(today.id,"Holiday");check(quick.scheduledOn("2026-10-29")==null,"Cancelled date hides roster marks");fail(()->quick.markFromRoster(today.id,active,"In person","2026-10-29",people));quick.remove(today.id);check(quick.scheduledOn("2026-10-29")==null,"Deleted date hides roster marks");
  System.out.println("PASS: "+n+" meeting/schedule/attendance checks");
 }
}
